cypress_script:
describe('Challenging DOM Action Buttons', () => {
  it('should display action buttons correctly', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button').should('be.visible');
    cy.get('a.button.alert').should('be.visible');
    cy.get('a.button.success').should('be.visible');
  });

  it('should not navigate away from the page when clicking buttons', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button.alert').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button.success').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Challenging DOM Action Buttons', () => {
  test('should display action buttons correctly', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a.button')).toBeVisible();
    await expect(page.locator('a.button.alert')).toBeVisible();
    await expect(page.locator('a.button.success')).toBeVisible();
  });

  test('should not navigate away from the page when clicking buttons', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await page.locator('a.button.alert').click();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
    await page.locator('a.button.success').click();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
  });
});
